20	import * as zrUtil from 'zrender/src/core/util';
21	import Scale, { ScaleGetTicksOpt } from './Scale';
22	import * as numberUtil from '../util/number';
23	
24	// Use some method of IntervalScale
25	import IntervalScale from './Interval';
26	import {
27	    DimensionLoose, DimensionName, ParsedAxisBreakList, AxisBreakOption,
28	    ScaleTick
29	} from '../util/types';
