34	const fixRound = numberUtil.round;
35	const mathFloor = Math.floor;
36	const mathCeil = Math.ceil;
37	const mathPow = Math.pow;
38	const mathLog = Math.log;
39	
40	class LogScale extends IntervalScale {
41	
42	    static type = 'log';
43	    readonly type = 'log';
44	
45	    base = 10;
46	
47	    private _originalScale = new IntervalScale();
48	
49	    private _fixMin: boolean;
50	    private _fixMax: boolean;
51	
52	    /**
53	     * @param Whether expand the ticks to niced extent.
54	     */
55	    getTicks(opt?: ScaleGetTicksOpt): ScaleTick[] {
56	        opt = opt || {};
57	        const extent = this._extent.slice() as [number, number];
58	        const originalExtent = this._originalScale.getExtent();
59	
60	        const ticks = super.getTicks(opt);
61	        const base = this.base;
62	        const originalBreaks = this._originalScale._innerGetBreaks();
63	        const scaleBreakHelper = getScaleBreakHelper();
64	
65	        return zrUtil.map(ticks, function (tick) {
66	            const val = tick.value;
67	            let powVal = fixRound(mathPow(base, val));
68	            let roundingCriterion = null;
69	
70	            // Fix #4158
71	            if (val === extent[0] && this._fixMin) {
72	                roundingCriterion = originalExtent[0];
73	            }
74	            else if (val === extent[1] && this._fixMax) {
75	                roundingCriterion = originalExtent[1];
76	            }
77	
78	            let vBreak;
79	            if (scaleBreakHelper) {
80	                const transformed = scaleBreakHelper.getTicksLogTransformBreak(
81	                    tick,
82	                    base,
83	                    originalBreaks,
84	                    fixRoundingError
85	                );
86	                vBreak = transformed.vBreak;
87	                if (roundingCriterion == null) {
88	                    roundingCriterion = transformed.brkRoundingCriterion;
89	                }
90	            }
91	
92	            if (roundingCriterion != null) {
93	                powVal = fixRoundingError(powVal, roundingCriterion);
94	            }
95	
96	            return {
97	                value: powVal,
98	                break: vBreak,
99	            };
100	        }, this);
101	    }
102	
103	    protected _getNonTransBreaks(): ParsedAxisBreakList {
104	        return this._originalScale._innerGetBreaks();
105	    }
106	
107	    setExtent(start: number, end: number): void {
108	        this._originalScale.setExtent(start, end);
109	        const loggedExtent = logTransform(this.base, [start, end]);
110	        super.setExtent(loggedExtent[0], loggedExtent[1]);
111	    }
112	
113	    /**
114	     * @return {number} end
115	     */
116	    getExtent() {
117	        const base = this.base;
118	        const extent = super.getExtent();
119	        extent[0] = mathPow(base, extent[0]);
120	        extent[1] = mathPow(base, extent[1]);
121	
122	        // Fix #4158
123	        const originalExtent = this._originalScale.getExtent();
124	        this._fixMin && (extent[0] = fixRoundingError(extent[0], originalExtent[0]));
125	        this._fixMax && (extent[1] = fixRoundingError(extent[1], originalExtent[1]));
126	
127	        return extent;
128	    }
129	
130	    unionExtentFromData(data: SeriesData, dim: DimensionName | DimensionLoose): void {
131	        this._originalScale.unionExtentFromData(data, dim);
132	        const loggedOther = logTransform(this.base, data.getApproximateExtent(dim), true);
133	        this._innerUnionExtent(loggedOther);
134	    }
135	
136	    /**
137	     * Update interval and extent of intervals for nice ticks
138	     * @param approxTickNum default 10 Given approx tick number
139	     */
140	    calcNiceTicks(approxTickNum: number): void {
141	        approxTickNum = approxTickNum || 10;
142	        const extent = this._extent.slice() as [number, number];
143	        const span = this._getExtentSpanWithBreaks();
144	        if (!isFinite(span) || span <= 0) {
145	            return;
146	        }
147	
148	        let interval = numberUtil.quantity(span);
149	        const err = approxTickNum / span * interval;
150	
151	        // Filter ticks to get closer to the desired count.
152	        if (err <= 0.5) {
153	            interval *= 10;
154	        }
155	
156	        // Interval should be integer
157	        while (!isNaN(interval) && Math.abs(interval) < 1 && Math.abs(interval) > 0) {
158	            interval *= 10;
159	        }
160	
161	        const niceExtent = [
162	            fixRound(mathCeil(extent[0] / interval) * interval),
163	            fixRound(mathFloor(extent[1] / interval) * interval)
164	        ] as [number, number];
165	
166	        this._interval = interval;
167	        this._niceExtent = niceExtent;
168	    }
169	
170	    calcNiceExtent(opt: {
171	        splitNumber: number,
172	        fixMin?: boolean,
173	        fixMax?: boolean,
174	        minInterval?: number,
175	        maxInterval?: number
176	    }): void {
177	        super.calcNiceExtent(opt);
178	
179	        this._fixMin = opt.fixMin;
180	        this._fixMax = opt.fixMax;
181	    }
182	
183	    contain(val: number): boolean {
184	        val = mathLog(val) / mathLog(this.base);
185	        return super.contain(val);
186	    }
187	
188	    normalize(val: number): number {
189	        val = mathLog(val) / mathLog(this.base);
190	        return super.normalize(val);
191	    }
192	
193	    scale(val: number): number {
194	        val = super.scale(val);
195	        return mathPow(this.base, val);
196	    }
197	
198	    setBreaksFromOption(
199	        breakOptionList: AxisBreakOption[],
200	    ): void {
201	        const scaleBreakHelper = getScaleBreakHelper();
202	        if (!scaleBreakHelper) {
203	            return;
204	        }
205	        const {parsedOriginal, parsedLogged} = scaleBreakHelper.logarithmicParseBreaksFromOption(
206	            breakOptionList,
207	            this.base,
208	            zrUtil.bind(this.parse, this)
209	        );
210	        this._originalScale._innerSetBreak(parsedOriginal);
211	        this._innerSetBreak(parsedLogged);
212	    }
213	
214	}
215	
216	function fixRoundingError(val: number, originalVal: number): number {
217	    return fixRound(val, numberUtil.getPrecision(originalVal));
218	}
219	
220	
221	Scale.registerClass(LogScale);
222	
223	export default LogScale;
