622	function getTicksLogTransformBreak(
623	    tick: ScaleTick,
624	    logBase: number,
625	    logOriginalBreaks: ParsedAxisBreakList,
626	    fixRoundingError: (val: number, originalVal: number) => number
627	): {
628	    brkRoundingCriterion: number;
629	    vBreak: VisualAxisBreak | NullUndefined;
630	} {
631	    let vBreak: VisualAxisBreak | NullUndefined;
632	    let brkRoundingCriterion: number;
633	
634	    if (tick.break) {
635	        const brk = tick.break.parsedBreak;
636	        const originalBreak = find(logOriginalBreaks, brk => identifyAxisBreak(
637	            brk.breakOption, tick.break.parsedBreak.breakOption
638	        ));
639	        const vmin = fixRoundingError(Math.pow(logBase, brk.vmin), originalBreak.vmin);
640	        const vmax = fixRoundingError(Math.pow(logBase, brk.vmax), originalBreak.vmax);
641	        const gapParsed = {
642	            type: brk.gapParsed.type,
643	            val: brk.gapParsed.type === 'tpAbs'
644	                ? fixRound(Math.pow(logBase, brk.vmin + brk.gapParsed.val)) - vmin
645	                : brk.gapParsed.val,
646	        };
647	        vBreak = {
648	            type: tick.break.type,
649	            parsedBreak: {
650	                breakOption: brk.breakOption,
651	                vmin,
652	                vmax,
653	                gapParsed,
654	                gapReal: brk.gapReal,
655	            }
656	        };
657	        brkRoundingCriterion = originalBreak[tick.break.type];
658	    }
659	
660	    return {
661	        brkRoundingCriterion,
662	        vBreak,
663	    };
664	}
