666	function logarithmicParseBreaksFromOption(
667	    breakOptionList: AxisBreakOption[],
668	    logBase: number,
669	    parse: Scale['parse'],
670	): {
671	    parsedOriginal: AxisBreakParsingResult;
672	    parsedLogged: AxisBreakParsingResult;
673	} {
674	    const opt = {noNegative: true};
675	    const parsedOriginal = parseAxisBreakOption(breakOptionList, parse, opt);
676	
677	    const parsedLogged = parseAxisBreakOption(breakOptionList, parse, opt);
678	    const loggedBase = Math.log(logBase);
679	    parsedLogged.breaks = map(parsedLogged.breaks, brk => {
680	        const vmin = Math.log(brk.vmin) / loggedBase;
681	        const vmax = Math.log(brk.vmax) / loggedBase;
682	        const gapParsed = {
683	            type: brk.gapParsed.type,
684	            val: brk.gapParsed.type === 'tpAbs'
685	                ? (Math.log(brk.vmin + brk.gapParsed.val) / loggedBase) - vmin
686	                : brk.gapParsed.val,
687	        };
688	        return {
689	            vmin,
690	            vmax,
691	            gapParsed,
692	            gapReal: brk.gapReal,
693	            breakOption: brk.breakOption
694	        };
695	    });
696	
697	    return {parsedOriginal, parsedLogged};
